async function run(target?: string): Promise<string[]> {
	let stdout = "";
	const io: Io = {
		cwd: repo,
		env: { ...process.env, XDG_CONFIG_HOME: home, PI_CODING_AGENT_DIR: home, GITHUB_TOKEN: "test-token" },
		stdout: (text) => {
			stdout += text;
		},
		stderr: () => {},
		color: false,
	};
	await doctor(io, target === undefined ? {} : { target });
	return stdout.split("\n").filter((line) => / {2}plan\s+/.test(line));

describe("the --trust-head flag", () => {
	it.each([
		[["review", "#7"], false],
		[["review", "#7", "--trust-head"], true],
	])("passes the reviewer's word to the review only when given: %j", async (args, trustHead) => {
		const io = output();
		const review = vi.spyOn(commands, "review").mockResolvedValue(0);
		try {
			expect(await main(args as string[], io)).toBe(0);
			expect(review).toHaveBeenCalledExactlyOnceWith(io, "#7", {
				rerun: false,
				notes: false,
				walkthrough: true,
				trustHead,
				cold: false,
			});
		} finally {
			review.mockRestore();
		}
	});
